"""Build a no-zoom, draggable 6144-square planning preview with nine backgrounds."""
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2]
d=json.loads((ROOT/'docs/prototypes/百川宗门城镇资源规划数据_20261027.json').read_text(encoding='utf-8'))
HTML=r'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>百川九宫格·固定倍率体验</title><link rel="icon" href="data:,"><style>
*{box-sizing:border-box}body{margin:0;background:#eee9df;color:#34453d;font:15px/1.6 "Microsoft YaHei",sans-serif;overflow:hidden}header{height:102px;padding:14px 24px;border-bottom:1px solid #cbc3b3}h1{font-size:22px;margin:0}header p{margin:3px 0;color:#727a70;font-size:13px}button{font:inherit;color:inherit;background:#faf6ed;border:1px solid #cfc5b4;border-radius:5px;cursor:pointer;padding:5px 12px}main{height:calc(100vh - 102px);display:grid;grid-template-columns:minmax(0,1fr) 310px}#view{position:relative;overflow:hidden;background:#f5eedf;touch-action:none;cursor:grab;user-select:none}#view.dragging{cursor:grabbing}#world{width:6144px;height:6144px;position:absolute;left:0;top:0;transform-origin:0 0}#world svg{display:block;width:6144px;height:6144px}#badge{position:absolute;left:14px;top:12px;background:#fffbf0e8;padding:7px 12px;border:1px solid #d4ccba;border-radius:5px;pointer-events:none}aside{padding:16px;overflow:auto;border-left:1px solid #cfc5b4}aside p{font-size:13px;color:#727a70}.buttons{display:flex;gap:6px;flex-wrap:wrap;margin:12px 0}#overview{width:276px;height:276px;background:#f8f3e8;border:1px solid #c7beac;cursor:pointer}h2{font-size:19px;margin:14px 0 6px}.field{border-top:1px solid #ded6c8;padding:10px 0;font-size:13px}.node{cursor:pointer}.node text{font-family:"Microsoft YaHei";paint-order:stroke;stroke:#fff9e9;stroke-width:5px;stroke-linejoin:round;pointer-events:none}label{display:inline-block;margin:4px 8px 4px 0;font-size:13px}.note{font-size:12px;color:#8c7b62}#selected{font-size:14px}#world .node:hover{filter:brightness(.7)}
</style><header><h1>百川九宫格 · 固定倍率体验</h1><p>背景绘制目标：九块2048方图，整图6144方图。当前显示规划色块；尚未生成九张正式背景。</p><span class="note">拖拽或方向键浏览；滚轮不缩放。右侧小图只导航位置。相机浏览不代表角色移动，不消耗游戏时间。</span></header>
<main><div id="view" tabindex="0" aria-label="固定倍率地图，拖拽浏览"><div id="world"><svg id="map" viewBox="0 0 6144 6144"></svg></div><div id="badge"></div></div><aside><svg id="overview" viewBox="0 0 6144 6144" aria-label="分块导航小图"></svg><div class="buttons"><button data-go="玉虚仙宗">玉虚</button><button data-go="玄都天府">玄都</button><button data-go="无相圣宗">无相</button><button data-go="通济城">中部</button></div><label><input id="grid" type="checkbox" checked>分块边界</label><label><input id="roads" type="checkbox" checked>路线</label><label><input id="transit" type="checkbox" checked>空节点</label><h2 id="selected-title">点选一个地点</h2><div id="selected">地点图标仍为规划符号。背景块不控制地点归属，跨块没有场景切换。</div><div class="field" id="stats"></div><p>九宫格总览可以缩略显示；主地图始终保持同一倍率。窗口变大只增加可见范围。</p></aside></main><script id="dataset" type="application/json">__DATA__</script><script>
var data=JSON.parse(document.getElementById('dataset').textContent),NS='http://www.w3.org/2000/svg',view=document.getElementById('view'),world=document.getElementById('world'),map=document.getElementById('map'),mini=document.getElementById('overview'),camera={x:0,y:0},drag=null,moved=false,MINI=6144,colors={'玉虚':'#527a66','玄都':'#9a7554','无相':'#816783'};
function el(tag,attrs,parent){var e=document.createElementNS(NS,tag);Object.entries(attrs||{}).forEach(function(a){e.setAttribute(a[0],a[1])});if(parent)parent.append(e);return e}
function pts(items){return items.map(function(p){return p[0]*61.44+','+p[1]*61.44}).join(' ')}
var t=data.terrainPlanning;[map,mini].forEach(function(target){t.areas.forEach(function(a){el('polygon',{points:pts(a.polygon),fill:a.color},target)});t.ridges.forEach(function(a){el('polyline',{points:pts(a.points),fill:'none',stroke:'#c3bca9','stroke-width':16},target)});t.lakes.forEach(function(a){el('polygon',{points:pts(a.polygon),fill:'#b9d1d1'},target)});t.waters.forEach(function(a){el('polyline',{points:pts(a.points),fill:'none',stroke:'#a6c3ca','stroke-width':a.width*5},target)})});
var roads=el('g',{},map);data.routes.forEach(function(r){el('polyline',{points:pts(r.renderPoints||r.points),fill:'none',stroke:r.isResourceSpur?'#a1a18c':'#8e8778','stroke-width':r.isResourceSpur?1.5:2.2,opacity:r.isResourceSpur?.55:.7,'data-route':r.id},roads)});
var grid=el('g',{},map);data.backgroundPlan.chunks.forEach(function(c){var q=c.coreRect;el('rect',{x:q[0],y:q[1],width:q[2],height:q[3],fill:'none',stroke:'#a47753','stroke-width':3,'stroke-dasharray':'16 12'},grid);var text=el('text',{x:q[0]+22,y:q[1]+36,'font-size':24,fill:'#9b795b'},grid);text.textContent=c.id+' · '+c.title;el('rect',{x:q[0],y:q[1],width:q[2],height:q[3],fill:'none',stroke:'#c0b19a','stroke-width':12},mini)});
var transitions=el('g',{},map);data.transitNodes.forEach(function(n){el('circle',{cx:n.pos[0]*61.44,cy:n.pos[1]*61.44,r:n.routeFeature?5:n.isJunction?4.5:3.5,fill:'#f5eedf',stroke:'#8e8778','stroke-width':1.3},transitions)});
var categories={sect:'宗门',city:'城市',town:'镇',market:'坊市',village:'村落',dock:'渡口',wild:'野外'};
data.nodes.forEach(function(n){var x=n.pos[0]*61.44,y=n.pos[1]*61.44,r=n.type==='sect'?(n.level===1?32:22):n.type==='city'?24:n.resourceSite?15:10,c=n.type==='sect'?colors[n.camp]:n.type==='city'?'#a07835':n.resourceSite?'#528d8a':'#8a9e8c',g=el('g',{'class':'node',role:'button','aria-label':n.name,tabindex:0},map);el('circle',{cx:x,cy:y,r:r+9,fill:'transparent'},g);if(n.type==='sect')el('polygon',{points:x+','+(y-r)+' '+(x+r)+','+y+' '+x+','+(y+r)+' '+(x-r)+','+y,fill:c},g);else if(n.type==='city')el('rect',{x:x-r,y:y-r,width:r*2,height:r*2,rx:4,fill:c},g);else el('circle',{cx:x,cy:y,r:r,fill:c},g);var text=el('text',{x:x,y:y+r+24,'text-anchor':'middle','font-size':n.type==='sect'&&n.level===1?24:18,fill:c},g);text.textContent=n.name;g.addEventListener('click',function(){if(moved)return;select(n)});if(n.type==='sect'||n.type==='city')el('circle',{cx:x,cy:y,r:n.type==='sect'&&n.level===1?48:28,fill:c},mini)});
var frame=el('rect',{fill:'none',stroke:'#6c5036','stroke-width':24},mini),pin=el('circle',{cx:22*61.44,cy:74*61.44,r:11,fill:'#394b3d',stroke:'#fff9e9','stroke-width':5},map);
function update(){camera.x=Math.max(0,Math.min(6144-view.clientWidth,camera.x));camera.y=Math.max(0,Math.min(6144-view.clientHeight,camera.y));world.style.transform='translate('+(-camera.x)+'px,'+(-camera.y)+'px)';Object.entries({x:camera.x,y:camera.y,width:view.clientWidth,height:view.clientHeight}).forEach(function(a){frame.setAttribute(a[0],a[1])});var visible=data.nodes.filter(function(n){var x=n.pos[0]*61.44,y=n.pos[1]*61.44;return x>=camera.x&&x<=camera.x+view.clientWidth&&y>=camera.y&&y<=camera.y+view.clientHeight});document.getElementById('badge').textContent='倍率固定 1:1 · 当前视口 '+view.clientWidth+'×'+view.clientHeight+' · 可见地点 '+visible.length;document.getElementById('stats').textContent='背景9块／具名地点123／空节点313。示例角色位于玉虚，拖动仅浏览相机。'}
function select(n){document.getElementById('selected-title').textContent=n.name;var c=data.backgroundPlan.chunks.find(function(c){return c.nodes.includes(n.id)});document.getElementById('selected').textContent=(n.resourceSite?'野外·资源产地':categories[n.type])+' · '+c.id+'（'+c.title+'）'+(n.camp?'；站队倾向：'+n.camp:'')+(n.owner?'；归属：'+n.owner:'')+(n.policyNote?'；'+n.policyNote:'');roads.querySelectorAll('[data-route]').forEach(function(e){var r=data.routes.find(function(r){return r.id===e.dataset.route}),active=r.from===n.id||r.to===n.id;e.setAttribute('stroke',active?'#655f4f':r.isResourceSpur?'#a1a18c':'#8e8778');e.setAttribute('stroke-width',active?3:r.isResourceSpur?1.5:2.2);e.setAttribute('opacity',active?1:r.isResourceSpur?.55:.7)})}
function go(name){var n=data.nodes.find(function(n){return n.name===name});camera.x=n.pos[0]*61.44-view.clientWidth/2;camera.y=n.pos[1]*61.44-view.clientHeight/2;update();select(n)}
document.querySelectorAll('[data-go]').forEach(function(b){b.addEventListener('click',function(){go(b.dataset.go)})});document.getElementById('grid').addEventListener('change',function(e){grid.style.display=e.target.checked?'':'none'});document.getElementById('roads').addEventListener('change',function(e){roads.style.display=e.target.checked?'':'none'});document.getElementById('transit').addEventListener('change',function(e){transitions.style.display=e.target.checked?'':'none'});
view.addEventListener('pointerdown',function(e){if(e.button!==0)return;drag={x:e.clientX,y:e.clientY,cx:camera.x,cy:camera.y};moved=false;view.classList.add('dragging');view.focus()});window.addEventListener('pointermove',function(e){if(!drag)return;var dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.hypot(dx,dy)>4)moved=true;camera.x=drag.cx-dx;camera.y=drag.cy-dy;update()});window.addEventListener('pointerup',function(){drag=null;view.classList.remove('dragging')});view.addEventListener('wheel',function(e){e.preventDefault()},{passive:false});view.addEventListener('keydown',function(e){var deltas={ArrowLeft:[-96,0],a:[-96,0],ArrowRight:[96,0],d:[96,0],ArrowUp:[0,-96],w:[0,-96],ArrowDown:[0,96],s:[0,96]};var delta=deltas[e.key];if(delta){camera.x+=delta[0];camera.y+=delta[1];update();e.preventDefault()}});
mini.addEventListener('click',function(e){var rect=mini.getBoundingClientRect();camera.x=(e.clientX-rect.left)/rect.width*6144-view.clientWidth/2;camera.y=(e.clientY-rect.top)/rect.height*6144-view.clientHeight/2;update()});window.addEventListener('resize',update);go('玉虚仙宗');
</script></html>'''
out=ROOT/'docs/prototypes/百川九宫格固定倍率体验_20261027.html'
output=HTML.replace('__DATA__',json.dumps(d,ensure_ascii=False)).replace('空节点313',f'空节点{d["count"]["transit"]}')
out.write_text(output,encoding='utf-8')
print(str(out))
